using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using Valve.VR;

public partial class OrbitVR {
 static int grabPanel;static uint grabDevice;static string grabKind;
 static HmdMatrix34_t grabHand,grabFace,grabCurrent;static double grabWidth,currentWidth;
 static readonly TrackedDevicePose_t[] grabPoses=new TrackedDevicePose_t[OpenVR.k_unMaxTrackedDeviceCount];
 static HmdMatrix34_t Inverse(HmdMatrix34_t m){var r=new HmdMatrix34_t{m0=m.m0,m1=m.m4,m2=m.m8,m4=m.m1,m5=m.m5,m6=m.m9,m8=m.m2,m9=m.m6,m10=m.m10};r.m3=-(r.m0*m.m3+r.m1*m.m7+r.m2*m.m11);r.m7=-(r.m4*m.m3+r.m5*m.m7+r.m6*m.m11);r.m11=-(r.m8*m.m3+r.m9*m.m7+r.m10*m.m11);return r;}
 static bool TriggerHeld(uint device){var state=new VRControllerState_t();return system.GetControllerState(device,ref state,(uint)Marshal.SizeOf(typeof(VRControllerState_t)))&&(state.ulButtonPressed&(1UL<<33))!=0;}
 static object GrabCommand(Dictionary<string,object> c){int id=(int)Number(c,"panelId",0);string kind=Text(c,"action");if(kind=="end"){EndGrab();return new{moving=false};}ExtraPanel p;if(!extraPanels.TryGetValue(id,out p)||p.hidden)throw new Exception("Choose a visible screen.");if(kind!="move"&&kind!="resize")throw new Exception("Choose Move or Resize.");if(!interaction&&!fixture&&!OpenVR.Overlay.IsDashboardVisible())throw new Exception("Enable panel interaction first.");EndGrab();if(fixture)return new{moving=true,fixture=true};uint device=(uint)Number(c,"device",OpenVR.k_unTrackedDeviceIndexInvalid);if(device>=OpenVR.k_unMaxTrackedDeviceCount||system.GetTrackedDeviceClass(device)!=ETrackedDeviceClass.Controller){device=OpenVR.k_unTrackedDeviceIndexInvalid;foreach(var role in new[]{ETrackedControllerRole.LeftHand,ETrackedControllerRole.RightHand}){uint candidate=system.GetTrackedDeviceIndexForControllerRole(role);if(candidate<OpenVR.k_unMaxTrackedDeviceCount&&TriggerHeld(candidate)){device=candidate;break;}}}if(device>=OpenVR.k_unMaxTrackedDeviceCount)throw new Exception("Hold the trigger on Move or Resize, then move that controller.");system.GetDeviceToAbsoluteTrackingPose(ETrackingUniverseOrigin.TrackingUniverseStanding,0,grabPoses);if(!grabPoses[device].bPoseIsValid)throw new Exception("Controller tracking is unavailable.");if(focusedPanel==id)RestoreFocusedPanel();
  var origin=ETrackingUniverseOrigin.TrackingUniverseStanding;var face=Identity();if(p.placement.anchor=="pinned")Check(OpenVR.Overlay.GetOverlayTransformAbsolute(p.handle,ref origin,ref face));else {uint relative=0;Check(OpenVR.Overlay.GetOverlayTransformTrackedDeviceRelative(p.handle,ref relative,ref face));if(relative>=grabPoses.Length||!grabPoses[relative].bPoseIsValid)throw new Exception("Panel tracking is unavailable.");face=Multiply(grabPoses[relative].mDeviceToAbsoluteTracking,face);}grabPanel=id;grabDevice=device;grabKind=kind;grabHand=grabPoses[device].mDeviceToAbsoluteTracking;grabCurrent=grabFace=face;currentWidth=grabWidth=p.placement.width;return new{moving=true};
 }
 static void TickGrab(){if(grabPanel==0||fixture)return;ExtraPanel p;if(!extraPanels.TryGetValue(grabPanel,out p)){grabPanel=0;return;}system.GetDeviceToAbsoluteTrackingPose(ETrackingUniverseOrigin.TrackingUniverseStanding,0,grabPoses);if(!grabPoses[grabDevice].bPoseIsValid||!TriggerHeld(grabDevice)||(!interaction&&!OpenVR.Overlay.IsDashboardVisible())){EndGrab();return;}var hand=grabPoses[grabDevice].mDeviceToAbsoluteTracking;if(grabKind=="move"){grabCurrent=Multiply(Multiply(hand,Inverse(grabHand)),grabFace);Check(OpenVR.Overlay.SetOverlayTransformAbsolute(p.handle,ETrackingUniverseOrigin.TrackingUniverseStanding,ref grabCurrent));}else {currentWidth=Math.Max(.18,Math.Min(3,grabWidth+2*((hand.m3-grabHand.m3)*grabFace.m0+(hand.m7-grabHand.m7)*grabFace.m4+(hand.m11-grabHand.m11)*grabFace.m8)));Check(OpenVR.Overlay.SetOverlayWidthInMeters(p.handle,(float)currentWidth));}}
 static void ManipulationTests(){var pose=Rotation(37,-18);pose.m3=.2f;pose.m7=1.4f;pose.m11=-.3f;var product=Values(Multiply(pose,Inverse(pose)));var expected=Values(Identity());for(int i=0;i<12;i++)if(Math.Abs(product[i]-expected[i])>.00001)throw new Exception("Grab transform inverse failed.");var moved=pose;moved.m3+=.4f;var face=Identity();face.m11=-1;var result=Multiply(Multiply(moved,Inverse(pose)),face);if(Math.Abs(result.m3-.4)>.00001||Math.Abs(result.m11+1)>.00001)throw new Exception("Panel grab did not preserve its controller offset.");Emit(new{type="manipulation-selftest",passed=true,cases=2,liveController=false});}
 static void EndGrab(){ExtraPanel p;if(grabPanel==0)return;if(extraPanels.TryGetValue(grabPanel,out p)){if(grabKind=="move"){p.placement.anchor="pinned";p.placement.basis=Values(grabCurrent);p.placement.x=p.placement.y=p.placement.z=p.placement.yaw=p.placement.pitch=0;}p.placement.width=currentWidth;Emit(new{type="panel-placement",panelId=grabPanel,placement=p.placement,focusedPanel=focusedPanel});}grabPanel=0;}
}
